// This invitation displays an explicitly fictional profile; it never derives
// a proficiency level from the sample response count.
export function renderHome({ language = 'ru', resumable = false, button, linkButton, WHATSAPP, platform={bankCount:600,hasAttempt:false,finished:false} }) {
  const t = (ru, en) => language === 'en' ? en : ru;
  const esc = value => String(value).replace(/[&<>"']/g, character => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' })[character]);
  const wa = (ru, en) => esc(`${WHATSAPP}${WHATSAPP.includes('?') ? '&' : '?'}text=${encodeURIComponent(t(ru, en))}`);
  const sampleButton = () => linkButton(platform.hasAttempt?(platform.finished?t('Открыть мой разбор','Open my report'):t('Продолжить прохождение','Continue assessment')):t('Начать 120 заданий','Start 120 questions'),platform.hasAttempt?(platform.finished?'#my-report':'#assessment'):'#assessment-setup','primary');
  const profile = [
    [t('Чтение', 'Reading'), 'B2', 'reading'], [t('Аудирование', 'Listening'), 'A2', 'listening'],
    [t('Говорение', 'Speaking'), 'B1', 'speaking'], [t('Письмо', 'Writing'), 'B1', 'writing'],
    [t('Языковые средства', 'Language use'), 'B1', 'language']
  ];
  const steps = [
    [t('Попробуйте в деле', 'Try your English'), t('Сообщения, небольшие тексты и разговоры. Выберите ответ, который передаёт смысл ситуации.', 'Messages, short texts, and conversations. Choose the response that captures what the situation means.')],
    [t('Разберитесь в ответах', 'Understand your answers'), t('Получите карту наблюдений, объяснения ответов и четыре недели практики по обнаруженным трудностям.', 'Get an evidence map, answer explanations and four weeks of practice based on the difficulties observed.')],
    [t('Обсудите следующий шаг', 'Discuss your next step'), t('Пример полного отчёта покажет, как можно связать навыки, конкретные трудности и практику. Цели обучения обсудим лично.', 'The full example report connects skills, specific difficulties, and practice. We can discuss your learning goals together.')]
  ];
  const faq = [
    [t('Что я увижу после прохождения?', 'What will I see when I finish?'), t('Ваши ответы, правильные варианты и объяснения по заданиям на чтение, языковые средства и аудирование. Отдельно можно посмотреть вымышленный пример полного отчёта с разбором речи, письма и планом практики.', 'Your responses, the correct options, and explanations for language use, reading, and listening. Separately, you can explore a fictional full report with speaking and writing feedback and a practice plan.')],
    [t('Платформа уже определяет точный уровень?', 'Does the platform already determine a precise level?'), t('Он показывает, как вы справились со 120 заданиями выбранного варианта. Их результат пока не переводится в уровень CEFR. Для полной диагностики нужны проверенные задания, несколько источников свидетельств и отдельная оценка речи и письма.', 'It shows how you handled the 120 questions on your form. Their results are not converted into a CEFR level. A full assessment needs evaluated tasks, several sources of evidence, and separate speaking and writing assessment.')],
    [t('Нужно ли сейчас платить?', 'Do I need to pay now?'), t('Нет. Пилотное прохождение, разбор ответов и пример отчёта доступны бесплатно. Условия занятий и личного разбора можно обсудить с Нұрқанатом в WhatsApp.', 'No. The pilot assessment, response feedback and example report are free. You can discuss lessons and a personal assessment with Nurkanat on WhatsApp.')],
    [t('Как проверить говорение и письмо?', 'How can I check speaking and writing?'), t('Напишите Нұрқанату, чтобы обсудить разговор и самостоятельную письменную работу. Живой ответ помогает увидеть, как вы развиваете мысль, уточняете смысл и выражаете себя.', 'Message Nurkanat to discuss a conversation and an independent writing task. Your own responses reveal how you develop an idea, clarify meaning, and express yourself.')],
    [t('После образца обязательно записываться на курс?', 'Do I have to enrol afterwards?'), t('Нет. Разбор ответов полезен сам по себе. Если захотите продолжить вместе, обсудим вашу цель, подходящую группу и реальную нагрузку.', 'No. The answer explanations are useful on their own. If you would like to keep learning together, we can discuss your goal, a suitable group, and a realistic workload.')]
  ];
  return `<main id="main" class="home-page">
    <section class="home-hero wrap" aria-labelledby="home-title">
      <div class="home-hero-copy">
        <p class="home-eyebrow"><span aria-hidden="true"></span>${t('АНГЛИЙСКИЙ С НҰРҚАНАТОМ', 'ENGLISH WITH NURKANAT')}</p>
        <h1 id="home-title">${t('Ваш английский.<br><span>Теперь понятнее.</span>', 'Your English.<br><span>A little clearer.</span>')}</h1>
        <p class="home-hero-lead">${t('Что уже получается, где теряется смысл и с чего начать практику. Пройдите сфокусированный маршрут из большого банка и получите разбор своих ответов с планом практики.', 'See what comes naturally, where meaning gets lost, and what to practise. Follow a focused route through the question bank and get feedback on your own responses with a practice plan.')}</p>
        <div class="home-actions">${sampleButton()}${linkButton(t('Пример полного отчёта', 'See the full example report'), '#example-report', 'home-secondary')}</div>
        <div class="home-meta"><span>${t('Бесплатная пилотная версия', 'Free pilot version')}</span><span>16+</span><span>${t('Без таймера', 'No timer')}</span></div>
        <p class="home-sample-limit">${t('600 заданий в банке · 120 в прохождении. CEFR-уровень ещё требует проверки на данных учеников.', '600 questions in the bank · 120 in one attempt. CEFR-level claims still require learner validation.')}</p>
      </div>
      <div class="home-report-scene">
        <div class="home-report-orbit" aria-hidden="true"></div><span class="home-report-spark" aria-hidden="true">✳</span>
        <article class="home-report" aria-label="${t('Вымышленный пример профиля навыков', 'Fictional skill profile example')}">
          <div class="home-report-top"><span>${t('ПРОФИЛЬ НАВЫКОВ', 'YOUR SKILL PROFILE')}</span><span class="home-example-tag">${t('Пример', 'Example')}</span></div>
          <h2>${t('У каждого навыка<br>своя история.', 'Every skill has<br>its own story.')}</h2>
          <p class="home-report-person">${t('Данияр · вымышленный пример', 'Daniyar · fictional example')}</p>
          <div class="home-profile">${profile.map(([label, level, skill]) => `<div class="home-profile-row home-profile-${skill}"><span>${label}</span><span class="home-profile-rule" aria-hidden="true"></span><strong>${level}</strong></div>`).join('')}</div>
          <div class="home-report-insight"><span aria-hidden="true">↗</span><p>${t('Опора — чтение.<br><strong>Следующий фокус — изменения в разговоре.</strong>', 'Build on reading.<br><strong>Next focus: tracking changes in conversation.</strong>')}</p></div>
          <p class="home-report-caption">${t('Иллюстрация отчёта, не ваш результат.', 'An illustration of the report, not your result.')}</p>
        </article>
        <div class="home-floating-note"><span aria-hidden="true">✓</span><p>${t('Ваш английский.<br><strong>Ваш следующий шаг.</strong>', 'Your English.<br><strong>Your next step.</strong>')}</p></div>
      </div>
    </section>
    <div class="home-skill-band"><div class="wrap"><span>${t('Чтение', 'Reading')}</span><span aria-hidden="true">+</span><span>${t('Языковые средства', 'Language use')}</span><span aria-hidden="true">+</span><span>${t('Аудирование', 'Listening')}</span><span aria-hidden="true">→</span><span>${t('Понятный разбор', 'Clear explanations')}</span></div></div>
    <section class="home-section wrap home-method" aria-labelledby="home-method-title">
      <div class="home-section-heading"><div><p class="home-kicker">01 / ${t('ОТ ВОПРОСОВ К ЯСНОСТИ', 'FROM QUESTIONS TO CLARITY')}</p><h2 id="home-method-title">${t('Понимать свой английский.<br>И видеть, куда двигаться.', 'Understand your English.<br>See where to go next.')}</h2></div><p>${t('Можно легко читать и теряться в разговоре. Поэтому полезно смотреть на конкретные навыки и ответы.', 'You might read comfortably and lose track in a conversation. Looking at individual skills and responses makes the difference visible.')}</p></div>
      <div class="home-steps">${steps.map(([title, text], i) => `<article><span class="home-step-number">0${i + 1}</span><h3>${title}</h3><p>${text}</p></article>`).join('')}</div>
    </section>
    <section class="home-sample-section wrap" aria-labelledby="home-sample-title"><div class="home-sample-panel">
      <div class="home-sample-copy"><p class="home-kicker">${t('БОЛЬШЕ КОНТЕКСТА ДЛЯ КАЖДОГО НАВЫКА', 'MORE EVIDENCE FOR EACH SKILL')}</p><h2 id="home-sample-title">${t('Английский<br>в реальных ситуациях.', 'English.<br>In real situations.')}</h2><p>${t('Уловить просьбу. Понять точку зрения. Удержать изменившуюся договорённость. Посмотрите, как вы справляетесь с разными задачами.', 'Understand a request. Follow a point of view. Keep track when a plan changes. Try different ways of putting your English to work.')}</p><div class="home-actions">${sampleButton()}</div><span class="home-sample-free">${t('Бесплатно · можно сделать паузу', 'Free · pause whenever you need')}</span></div>
      <div class="home-sample-details"><div class="home-domain-counts">${[[t('Языковые средства', 'Language use'), 'Aa'], [t('Чтение', 'Reading'), '≡'], [t('Аудирование', 'Listening'), '◖◗']].map(([label, icon]) => `<div><span class="home-domain-icon" aria-hidden="true">${icon}</span><span>${label}</span><strong>40</strong></div>`).join('')}</div><div class="home-sample-outcome"><span class="home-check" aria-hidden="true">✓</span><p>${t('После прохождения — ваши ответы, ключи и объяснения. Вы сможете вернуться к каждой ситуации.', 'Afterwards, explore your responses, the answer keys, and explanations. You can return to every situation.')}</p></div></div>
    </div></section>
    <section class="home-section wrap home-teacher-section" aria-labelledby="home-teacher-title"><div class="home-teacher">
      <div class="home-teacher-image"><img src="assets/teacher.jpg" alt="${t('Нұрқанат Дайраш, преподаватель английского', 'Nurkanat Dairash, English teacher')}" width="280" height="320" loading="lazy"><span>${t('Нұрқанат Дайраш', 'Nurkanat Dairash')}</span></div>
      <div class="home-teacher-copy"><p class="home-kicker">${t('ВАШ ПРЕПОДАВАТЕЛЬ', 'YOUR TEACHER')}</p><h2 id="home-teacher-title">${t('За результатом —<br>живой разговор.', 'Behind the result,<br>a real conversation.')}</h2><p>${t('Я Нұрқанат. Давайте обсудим, для чего вам английский и какие навыки важнее именно сейчас. Речь и письмо дополнят картину — и помогут выбрать подходящую группу.', 'I’m Nurkanat. Let’s talk about why you need English and which skills matter most right now. Speaking and writing add to the picture and help us find a suitable group.')}</p><div class="home-actions"><a class="button home-whatsapp" href="${wa('Здравствуйте, Нұрқанат! Хочу обсудить мой английский и подходящий формат обучения.', 'Hello Nurkanat! I would like to discuss my English and a suitable learning format.')}" target="_blank" rel="noopener noreferrer">${t('Написать в WhatsApp', 'Message on WhatsApp')} <span aria-hidden="true">↗</span></a><a class="home-text-link" href="https://nurkanat-tau.github.io/#about" target="_blank" rel="noopener noreferrer">${t('Больше обо мне', 'More about me')} <span aria-hidden="true">↗</span></a></div></div><span class="home-teacher-monogram" aria-hidden="true">n.</span>
    </div></section>
    <section class="home-courses" aria-labelledby="home-courses-title"><div class="wrap">
      <div class="home-section-heading"><div><p class="home-kicker">02 / ${t('УЧИТЬСЯ В СВОЁМ ТЕМПЕ', 'FIND YOUR LEARNING PACE')}</p><h2 id="home-courses-title">${t('Следующий шаг.<br>В вашем ритме.', 'Your next step.<br>At your pace.')}</h2></div><p>${t('Выберите формат, который впишется в вашу жизнь. Группу, расписание и нагрузку обсудим с учётом вашей цели.', 'Choose a format that fits your life. We will discuss your group, schedule, and workload around your goal.')}</p></div>
      <div class="home-course-grid">
        <article class="home-course"><span class="home-course-tag">${t('ПОСЛЕДОВАТЕЛЬНЫЙ ТЕМП', 'A STEADY PACE')}</span><h3>${t('Стандартный курс', 'Standard course')}</h3><p>${t('Встроить регулярный английский в работу, учёбу и повседневную жизнь. С временем на практику между занятиями.', 'Build regular English study around work, study, and everyday life, with time to practise between lessons.')}</p><div class="home-duration"><strong>6</strong><span>${t('месяцев<br>примерно на программу уровня', 'months<br>approximately per level programme')}</span></div><a class="button home-course-link" href="${wa('Здравствуйте, Нұрқанат! Расскажите, пожалуйста, о стандартном курсе: расписании, нагрузке и подходящей группе.', 'Hello Nurkanat! Please tell me about the standard course, including its schedule, workload, and a suitable group.')}" target="_blank" rel="noopener noreferrer">${t('Обсудить стандартный курс', 'Discuss the standard course')} <span aria-hidden="true">↗</span></a></article>
        <article class="home-course"><span class="home-course-tag">${t('БОЛЬШЕ ПРАКТИКИ В НЕДЕЛЮ', 'MORE PRACTICE EACH WEEK')}</span><h3>${t('Интенсив', 'Intensive course')}</h3><p>${t('Для тех, кто готов выделить больше времени на занятия и самостоятельную практику каждую неделю.', 'For learners ready to make more time each week for lessons and independent practice.')}</p><div class="home-duration"><strong>3</strong><span>${t('месяца<br>примерно на программу уровня', 'months<br>approximately per level programme')}</span></div><a class="button primary home-course-link" href="${wa('Здравствуйте, Нұрқанат! Хочу узнать об интенсиве: расписании, недельной нагрузке и подходящей группе.', 'Hello Nurkanat! I would like to know about the intensive course, its schedule, weekly workload, and a suitable group.')}" target="_blank" rel="noopener noreferrer">${t('Обсудить интенсив', 'Discuss the intensive course')} <span aria-hidden="true">↗</span></a></article>
      </div><p class="home-course-note">${t('Сроки — ориентир длительности программы, не гарантия перехода на следующий CEFR-уровень. Стоимость, доступность группы и включённая поддержка уточняются лично.', 'Durations describe the programme, not a guaranteed move to the next CEFR level. Confirm fees, group availability, and included support directly.')}</p>
    </div></section>
    <section class="home-section wrap home-faq" aria-labelledby="home-faq-title"><div><p class="home-kicker">03 / ${t('ПЕРЕД НАЧАЛОМ', 'BEFORE YOU BEGIN')}</p><h2 id="home-faq-title">${t('Всё понятно.<br>Даже до первого<br>вопроса.', 'A little clarity.<br>Before the<br>first question.')}</h2><a class="home-text-link" href="${wa('Здравствуйте, Нұрқанат! У меня есть вопрос об образце диагностики.', 'Hello Nurkanat! I have a question about the assessment sample.')}" target="_blank" rel="noopener noreferrer">${t('Задать свой вопрос', 'Ask your question')} <span aria-hidden="true">↗</span></a></div><div class="home-faq-list">${faq.map(([question, answer]) => `<details><summary><span>${question}</span><span class="home-faq-plus" aria-hidden="true">+</span></summary><p>${answer}</p></details>`).join('')}</div></section>
    <section class="home-final wrap"><div><p class="home-kicker">${t('НАЧНИТЕ С ПОНИМАНИЯ', 'START WITH UNDERSTANDING')}</p><h2>${t('Ваш английский уже есть.<br>Посмотрите на него внимательнее.', 'Your English is already there.<br>Take a closer look.')}</h2></div><div class="home-final-action">${sampleButton()}<span>${t('120 заданий · бесплатно', '120 questions · free')}</span></div></section>
  </main>`;
}

